export const GTSUITE_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/gtsuite-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGtSuiteStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GTSUITE_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
